-- ── 12. Additional news posts ─────────────────────────────────────────────
INSERT INTO public.news_posts
  (id, title, slug, excerpt, content, category, author_id, published_at, is_published)
VALUES
  ('50000000-0000-0000-0000-000000000005',
   'BlazeSA Takes Clutch Gaming FC26 Season Opener',
   'blazesa-takes-clutch-fc26-season-opener',
   'BlazeSA dominated the FC26 bracket at Clutch Gaming, defeating Rama22 3-1 in the grand final.',
   'The first major NexCade event of 2026 delivered at Clutch Gaming in Benoni. Eight players entered, one left as champion.

BlazeSA (Thabo Mokoena) was clinical throughout, dropping only one game on his way to the final where he beat Rama22 3-1 in a tense decider.

Top 4: 1. BlazeSA (100 pts) 2. Rama22 (60 pts) 3. Theeee (40 pts) 4. Nova (25 pts).

BlazeSA sits top of the 2026-S1 leaderboard. The next Clutch Gaming event is already being planned.',
   'Recap','00000000-0000-0000-0000-000000000001','2026-01-19 09:00:00+00',true),

  ('50000000-0000-0000-0000-000000000006',
   'Recap: Battle Dome MK1 Invitational — Nova Reigns',
   'recap-battle-dome-mk1-invitational',
   'Nova won the Battle Dome MK1 Invitational with a dominant 3-0 grand final performance against Slinky.',
   'East London hosted NexCade''s most anticipated MK1 event of the season and Nova delivered a masterclass. A clean 3-0 over Slinky in the grand final sent the crowd wild.

Top 4: 1. Nova (100 pts) 2. Slinky (60 pts) 3. Rama22 (40 pts) 4. LevelUpArcade (25 pts).

Nova is now in contention for the S1 season title going into the final stretch.',
   'Recap','00000000-0000-0000-0000-000000000002','2026-03-30 09:00:00+00',true),

  ('50000000-0000-0000-0000-000000000007',
   'Season 2026-S1 Wrap: Slinky Is Your Season Champion',
   '2026-s1-wrap-slinky-season-champion',
   'Slinky accumulated 250 season points across five events to claim the inaugural NexCade season title.',
   'Season 2026-S1 is over. After five events Slinky (Sipho Nkosi) finishes on top with 250 points, earning the first ever NexCade season championship.

Final S1 top 5: Slinky 250, BlazeSA 215, Vexx 180, Jinx 170, Nova 195.

Slinky''s Neon Rift Tekken8 Monthly win was his defining moment, going undefeated to clinch the title. His consistency across KOFXV and MK1 events sealed it.

Season 2 starts in April. New leaderboard, same hunger.',
   'Community','00000000-0000-0000-0000-000000000001','2026-04-01 09:00:00+00',true),

  ('50000000-0000-0000-0000-000000000008',
   'Live Today: Kombat Zone MK1 + Clutch FC26 Spring Cup',
   'live-today-kombat-zone-mk1-clutch-fc26-spring-cup',
   'Two NexCade events are running live today across Gauteng.',
   'Today is a big day for NexCade. Two events are live simultaneously.

Kombat Zone MK1 Battle (Sandton) — Quarter-finals done. BlazeSA, Jinx, Slinky, and Nova advance to the semis. Watch the bracket live on the tournament page.

Clutch Gaming FC26 Spring Cup (Benoni) — Group stage complete. BlazeSA topped Group A undefeated, Slinky topped Group B. Knockout starts shortly.

Both pages update in real time. Follow along on NexCade.',
   'News','00000000-0000-0000-0000-000000000001','2026-06-12 14:00:00+00',true)

ON CONFLICT (id) DO NOTHING;
